#!/usr/bin/env python3
"""Build diagramize's generated files from docs/diagramize/*.mmd and the skill's
references/mermaid-light.json and mermaid-dark.json:

- references/mermaid-light-frontmatter.yaml: the light config as the YAML
  frontmatter diagramize copies into each Mermaid block of a Markdown file.
- docs/diagramize/preview.md: each kind as a Markdown file shows it.
- docs/diagramize/preview.html: each kind on HTML pages, with mermaid-light.json on
  a light page and mermaid-dark.json on a dark page, plus the Markdown form on a
  dark page.

Before writing anything, mermaid-cli draws the preview.md blocks twice, once with
the light frontmatter and once with the dark config in the same form. Every block
must come out as an SVG with the config's primaryColor in it, which catches a
broken source and frontmatter that YAML misread. The check runs mermaid-cli
through npx; set MMDC to an mmdc binary to use that instead. The pre-commit hook
in .githooks/ runs this script."""

import html
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
REFS = ROOT / "plugins/explain/skills/diagramize/references"
LIGHT = REFS / "mermaid-light.json"
DARK = REFS / "mermaid-dark.json"
FRONTMATTER = REFS / "mermaid-light-frontmatter.yaml"
OUT = ROOT / "docs/diagramize"
ORDER = ["flowchart", "sequence", "state", "class", "er"]
MERMAID = "12.2.0"
CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
TIMEOUT = 300  # seconds per mermaid-cli run; the first npx run also installs it
REFS_LINK = "../../plugins/explain/skills/diagramize/references"
GENERATED = ("Generated by scripts/render-diagramize-preview.py. Edit docs/diagramize/*.mmd "
             "or plugins/explain/skills/diagramize/references/mermaid-*.json, not this file.")
# Each figure in preview.html: (CSS class, caption, config name).
FIGURES = [
    ("light", "HTML or Markdown, light page", "light"),
    ("dark", "HTML, dark page", "dark"),
    ("dark", "Markdown, dark page", "light"),
]


def yaml(value, indent=0):
    """Write a JSON config as YAML, with every string quoted: YAML reads an
    unquoted #rrggbb as a comment."""
    lines = []
    for key, item in value.items():
        pad = "  " * indent
        if isinstance(item, dict):
            lines.append(f"{pad}{key}:")
            lines.extend(yaml(item, indent + 1))
        else:
            lines.append(f"{pad}{key}: {json.dumps(item)}")
    return lines


def frontmatter(config):
    return "\n".join(["---", "config:", *yaml(config, 1), "---"])


def markdown(sources, config, lead):
    parts = list(lead)
    for src in sources:
        parts += ["", f"## {src.stem}", "", "```mermaid", frontmatter(config),
                  src.read_text().rstrip("\n"), "```"]
    return "\n".join(parts) + "\n"


def preview_markdown(sources, light):
    return markdown(sources, light, [
        f"<!-- {GENERATED} -->",
        "",
        "# diagramize preview",
        "",
        "Each Mermaid kind as diagramize writes it in a Markdown file, with the settings from "
        f"[`mermaid-light.json`]({REFS_LINK}/mermaid-light.json). Text sits on light fills, "
        "except sequence messages and loop conditions, which use a mid blue that reads on "
        "light and dark pages. Each viewer draws the diagrams with its own Mermaid version, "
        "so details can differ. [`preview.html`](preview.html) shows the exact look of "
        "diagramize's HTML pages.",
    ])


def frontmatter_file(light):
    return "\n".join([
        "# Generated from mermaid-light.json by scripts/render-diagramize-preview.py.",
        "# Copy the lines from the first --- to the last --- to the top of each Mermaid block.",
        frontmatter(light),
    ]) + "\n"


def mmdc_command():
    if os.environ.get("MMDC"):
        return [os.environ["MMDC"]]
    if shutil.which("npx"):
        return ["npx", "-y", "--prefer-offline", f"@mermaid-js/mermaid-cli@{MERMAID}"]
    sys.exit("npx not found. Install Node.js, or set MMDC to an mmdc binary.")


def check(sources, configs):
    """Draw every source in its Markdown form with each config, and fail unless each
    block comes out as an SVG that carries the config's colours."""
    command = mmdc_command()
    env = dict(os.environ)
    if "PUPPETEER_EXECUTABLE_PATH" not in env and os.access(CHROME, os.X_OK):
        env["PUPPETEER_EXECUTABLE_PATH"] = CHROME
    with tempfile.TemporaryDirectory() as tmp:
        for name, config in configs.items():
            src = Path(tmp) / f"{name}.md"
            src.write_text(markdown(sources, config, [f"# {name}"]))
            try:
                result = subprocess.run(
                    [*command, "-q", "-i", str(src), "-o", f"{tmp}/{name}-out.md"],
                    env=env, capture_output=True, text=True, timeout=TIMEOUT,
                )
            except subprocess.TimeoutExpired:
                sys.exit(f"mermaid-cli did not finish within {TIMEOUT} s. If npx is installing it, "
                         f"run `npx -y @mermaid-js/mermaid-cli@{MERMAID} --version` once, "
                         "or set MMDC to an mmdc binary.")
            if result.returncode != 0:
                sys.exit(f"mermaid-cli failed on the {name} blocks:\n{result.stderr.strip()}")
            colour = config["themeVariables"]["primaryColor"].lower()
            for i, src_file in enumerate(sources, 1):
                svg = Path(tmp) / f"{name}-out-{i}.svg"
                if not svg.exists() or colour not in svg.read_text().lower():
                    sys.exit(f"{src_file.name} was not drawn with the {name} config's {colour}")
    print(f"mermaid-cli drew all {len(sources)} diagrams with each config")


def preview_html(sources, configs):
    sections = []
    for src in sources:
        code = html.escape(src.read_text().rstrip("\n"))
        figures = "\n".join(
            f'      <figure class="{cls}"><figcaption>{caption}</figcaption>'
            f'<pre class="mermaid" data-config="{name}">\n{code}\n      </pre></figure>'
            for cls, caption, name in FIGURES
        )
        sections.append(f"""  <section>
    <h2>{src.stem}</h2>
    <div class="row">
{figures}
    </div>
    <details><summary>Source: {src.name}</summary><pre class="src">{code}</pre></details>
  </section>""")

    return f"""<!doctype html>
<!-- {GENERATED} -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>diagramize preview</title>
<style>
  body {{ margin: 0 auto; max-width: 1440px; padding: 24px 16px; background: #ffffff;
         color: #1f2937; font: 15px/1.5 system-ui, sans-serif; }}
  h1 {{ font-size: 1.5rem; margin: 0 0 4px; }}
  p.lead {{ margin: 0 0 24px; color: #4b5563; max-width: 72ch; }}
  section {{ border-top: 1px solid #e5e7eb; padding: 16px 0 24px; }}
  h2 {{ font-size: 1.1rem; margin: 0 0 12px; }}
  .row {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }}
  @media (max-width: 900px) {{ .row {{ grid-template-columns: 1fr; }} }}
  figure {{ margin: 0; padding: 12px; border-radius: 8px; border: 1px solid #e5e7eb; min-width: 0; }}
  figure.light {{ background: #ffffff; }}
  figure.dark {{ background: #0d1117; border-color: #0d1117; }}
  figcaption {{ font-size: 12px; color: #6b7280; margin-bottom: 8px; }}
  figure.dark figcaption {{ color: #9ca3af; }}
  pre.mermaid {{ margin: 0; text-align: center; overflow-x: auto; }}
  pre.mermaid svg {{ max-width: 100%; height: auto; }}
  details {{ margin-top: 12px; }}
  pre.src {{ background: #f3f4f6; padding: 12px; overflow-x: auto; font-size: 13px; }}
  code {{ background: #f3f4f6; padding: 0 4px; }}
</style>
</head>
<body>
  <h1>diagramize preview</h1>
  <p class="lead">Each Mermaid kind as diagramize draws it. HTML pages use <code>mermaid-light.json</code> on a light page and <code>mermaid-dark.json</code> on a dark page. Markdown files always use <code>mermaid-light.json</code>, because a Markdown block cannot follow the viewer's colour scheme.</p>
{chr(10).join(sections)}
<script src="https://cdn.jsdelivr.net/npm/mermaid@{MERMAID}/dist/mermaid.min.js"></script>
<script>
  const configs = {json.dumps(configs, indent=2)};
  (async () => {{
    let n = 0;
    for (const el of document.querySelectorAll("pre.mermaid")) {{
      mermaid.initialize({{ startOnLoad: false, ...configs[el.dataset.config] }});
      const {{ svg }} = await mermaid.render(`diagram-${{n++}}`, el.textContent);
      el.innerHTML = svg;
    }}
  }})();
</script>
</body>
</html>
"""


def main():
    found = sorted(p.stem for p in OUT.glob("*.mmd"))
    unknown = [n for n in found if n not in ORDER]
    missing = [n for n in ORDER if n not in found]
    if unknown or missing:
        sys.exit(f"sources and ORDER differ: unknown {unknown}, missing {missing}")
    sources = [OUT / f"{n}.mmd" for n in ORDER]
    configs = {"light": json.loads(LIGHT.read_text()), "dark": json.loads(DARK.read_text())}
    check(sources, configs)
    outputs = {
        FRONTMATTER: frontmatter_file(configs["light"]),
        OUT / "preview.html": preview_html(sources, configs),
        OUT / "preview.md": preview_markdown(sources, configs["light"]),
    }
    for path, text in outputs.items():
        path.write_text(text)
        print(f"Wrote {path.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
